{
  "tables": [
    {
      "table": "marts.dim_sku",
      "description": "One row per SKU with its units and VAT rate."
    },
    {
      "table": "marts.dim_store",
      "description": "One row per store, with its POS sync state at the snapshot."
    },
    {
      "table": "marts.fct_goods_received",
      "description": "Stock received by each store, one row per batch, from suppliers or from other stores. Includes the opening stock received before the sales window."
    },
    {
      "table": "marts.fct_inventory_batch",
      "description": "Stock at the snapshot, one row per batch, in base units. On-hand still includes stock reserved for transfers in transit and expired stock that waits for the monthly write-off."
    },
    {
      "table": "marts.fct_returns",
      "description": "One row per returned item, with the return date and the original sale date when known."
    },
    {
      "table": "marts.fct_sales",
      "description": "One row per sales line from both POS vendors, retries removed, base units, with and without VAT."
    },
    {
      "table": "marts.fct_transfers",
      "description": "Store to store transfers in base units."
    },
    {
      "table": "marts.metricflow_time_spine",
      "description": "One row per day for MetricFlow's cumulative windows and time offsets."
    }
  ]
}

{
  "table": "marts.fct_sales",
  "columns": [
    {
      "name": "sales_line_id",
      "type": "VARCHAR",
      "description": "Vendor, receipt and line number joined."
    },
    {
      "name": "pos_vendor",
      "type": "VARCHAR",
      "description": "POS vendor, A or B."
    },
    {
      "name": "receipt_no",
      "type": "VARCHAR",
      "description": "Receipt number. Not unique per SKU, a receipt can hold the same SKU twice."
    },
    {
      "name": "line_no",
      "type": "INTEGER",
      "description": "Line number within the receipt."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store code."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "business_date",
      "type": "DATE",
      "description": "Local date of the sale."
    },
    {
      "name": "sold_at",
      "type": "TIMESTAMP",
      "description": "Local time of the sale."
    },
    {
      "name": "uom_code",
      "type": "VARCHAR",
      "description": "Unit sold."
    },
    {
      "name": "qty",
      "type": "INTEGER",
      "description": "Quantity in uom_code."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "vat_rate",
      "type": "DECIMAL(5,4)",
      "description": "VAT rate as a fraction."
    },
    {
      "name": "unit_price_incl_vat",
      "type": "BIGINT",
      "description": "Shelf price of one uom_code, VAT included."
    },
    {
      "name": "gross_incl_vat",
      "type": "BIGINT",
      "description": "Before discount, VAT included."
    },
    {
      "name": "discount_incl_vat",
      "type": "BIGINT",
      "description": "Discount, VAT included."
    },
    {
      "name": "amount_incl_vat",
      "type": "BIGINT",
      "description": "Paid, VAT included."
    },
    {
      "name": "gross_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Before discount, VAT excluded."
    },
    {
      "name": "discount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Discount, VAT excluded."
    },
    {
      "name": "amount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Paid, VAT excluded."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Weighted average cost of one base unit of the SKU at this store (DR-008)."
    },
    {
      "name": "cogs_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of goods sold for the line, qty_base times unit_cost_excl_vat."
    }
  ]
}

{
  "table": "marts.fct_goods_received",
  "columns": [
    {
      "name": "goods_received_id",
      "type": "VARCHAR",
      "description": "ERP batch id of the receipt."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Receiving store."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Supplier lot number."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date received."
    },
    {
      "name": "source_type",
      "type": "VARCHAR",
      "description": "purchase_order or transfer."
    },
    {
      "name": "source_doc",
      "type": "VARCHAR",
      "description": "Purchase order or transfer number."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity received in base units."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of one base unit, VND, VAT excluded."
    },
    {
      "name": "received_value_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of the whole receipt, VAT excluded."
    }
  ]
}

{
  "table": "marts.fct_inventory_batch",
  "columns": [
    {
      "name": "batch_id",
      "type": "VARCHAR",
      "description": "ERP batch id."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store holding the batch."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Supplier lot number."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date the batch arrived at this store."
    },
    {
      "name": "expires_on",
      "type": "DATE",
      "description": "Expiry date of the lot."
    },
    {
      "name": "days_to_expiry",
      "type": "BIGINT",
      "description": "Days from the snapshot date to expiry. Negative when already expired."
    },
    {
      "name": "source_type",
      "type": "VARCHAR",
      "description": "purchase_order or transfer."
    },
    {
      "name": "source_doc",
      "type": "VARCHAR",
      "description": "Purchase order or transfer number."
    },
    {
      "name": "on_hand_qty_base",
      "type": "INTEGER",
      "description": "Quantity on hand at the snapshot, base units."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of one base unit from this batch, VND, VAT excluded."
    },
    {
      "name": "on_hand_value_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "on_hand_qty_base times unit_cost_excl_vat."
    },
    {
      "name": "snapshot_date",
      "type": "DATE",
      "description": "Date the stock position refers to."
    }
  ]
}

{
  "table": "marts.dim_store",
  "columns": [
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store code, for example NW001."
    },
    {
      "name": "store_name",
      "type": "VARCHAR",
      "description": "Store name."
    },
    {
      "name": "district_code",
      "type": "VARCHAR",
      "description": "District the store belongs to."
    },
    {
      "name": "district_name",
      "type": "VARCHAR",
      "description": "District name."
    },
    {
      "name": "opened_on",
      "type": "DATE",
      "description": "Date the store opened. Sell-through answers use it to flag new stores (DR-011)."
    },
    {
      "name": "days_open",
      "type": "BIGINT",
      "description": "Days between opening and the snapshot date."
    },
    {
      "name": "is_newly_opened",
      "type": "BOOLEAN",
      "description": "Opened in the 31 days before the snapshot."
    },
    {
      "name": "is_open_24h",
      "type": "BOOLEAN",
      "description": "Open around the clock."
    },
    {
      "name": "pos_vendor",
      "type": "VARCHAR",
      "description": "POS vendor, A or B."
    },
    {
      "name": "last_synced_at",
      "type": "TIMESTAMP",
      "description": "Last successful POS sync, local time."
    },
    {
      "name": "last_sync_attempt_at",
      "type": "TIMESTAMP",
      "description": "Last sync attempt, local time."
    },
    {
      "name": "last_sync_error",
      "type": "VARCHAR",
      "description": "Error of the last attempt, null when it worked."
    },
    {
      "name": "pos_data_through",
      "type": "DATE",
      "description": "Last business day whose sales have reached the warehouse. Answers use it to name lagging stores (DR-004)."
    },
    {
      "name": "pos_lag_days",
      "type": "BIGINT",
      "description": "Business days of sales still missing at the snapshot. 0 for a store synced through the day before."
    },
    {
      "name": "is_pos_sync_lagging",
      "type": "BOOLEAN",
      "description": "True when any day of sales is missing. Answers that include such a store must say so (DR-004)."
    }
  ]
}

{
  "query": "select (select sum(qty_base) from marts.fct_sales where business_date between '2026-08-01' and '2026-08-31') sold_aug, (select sum(qty_base) from marts.fct_sales where business_date>'2026-08-31') sold_after, (select sum(qty_base) from marts.fct_goods_received where received_on<'2026-08-01') rec_before, (select sum(qty_base) from marts.fct_goods_received where received_on between '2026-08-01' and '2026-08-31') rec_aug, (select sum(qty_base) from marts.fct_goods_received where received_on>'2026-08-31') rec_after, (select sum(on_hand_qty_base) from marts.fct_inventory_batch) onhand, (select min(business_date) from marts.fct_sales) mind, (select sum(qty_base) from marts.fct_sales where business_date<'2026-08-01') sold_before, (select max(snapshot_date) from marts.fct_inventory_batch) snap, (select sum(qty_base) from marts.fct_transfers) t"
}

{
  "query": "select store_code, opened_on, is_newly_opened, is_pos_sync_lagging, pos_lag_days, pos_data_through from marts.dim_store where is_newly_opened or is_pos_sync_lagging"
}

{
  "query": "select source_type, sum(case when received_on<'2026-08-01' then qty_base end) before, sum(case when received_on between '2026-08-01' and '2026-08-31' then qty_base end) aug, sum(case when received_on>'2026-08-31' then qty_base end) after from marts.fct_goods_received group by 1"
}

{
  "table": "marts.fct_transfers",
  "columns": [
    {
      "name": "transfer_no",
      "type": "VARCHAR",
      "description": "ERP transfer number."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Lot being transferred."
    },
    {
      "name": "from_store_code",
      "type": "VARCHAR",
      "description": "Sending store. Its on-hand still holds the stock until delivery. The `store` entity of this model."
    },
    {
      "name": "to_store_code",
      "type": "VARCHAR",
      "description": "Receiving store."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "transfer_status",
      "type": "VARCHAR",
      "description": "in_transit, delivered or cancelled."
    },
    {
      "name": "created_on",
      "type": "DATE",
      "description": "Date the transfer was created."
    },
    {
      "name": "shipped_on",
      "type": "DATE",
      "description": "Date the stock left the sending store. Set for cancelled transfers too."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date of delivery. Null unless delivered."
    },
    {
      "name": "updated_on",
      "type": "DATE",
      "description": "Date of the last status change."
    },
    {
      "name": "snapshot_date",
      "type": "DATE",
      "description": "Date the status refers to (the extract)."
    }
  ]
}

{
  "value": 0.5405,
  "replacement_metric": null,
  "caveats": [
    "NW029 (opened 2026-08-18) and NW030 (opened 2026-09-01) are newly opened stores (DR-011).",
    "NW029 and NW030 have POS sync lagging by 3 business days, with sales data through 2026-09-11 (DR-004). Sales for August are still complete for them."
  ],
  "explanation": "There is no ready-made sell-through metric, so I computed it as base units sold in August (1,478,251) divided by stock available. Available stock is the opening stock on 1 Aug (purchase-order receipts to date minus prior sales, 1,210,650) plus August purchase-order receipts (1,524,190). The result is about 54.05%. I left store-to-store transfers out because they net to zero across the chain. Returns and write-offs were not adjusted for, so the figure is an approximation, and the caveats are the data notes I found in the tables (the table notes cite DR-004 and DR-011), not a caveat list a tool returned."
}
